<?php
namespace App\Services;
use App\Models\{BillingWebhookEvent,SubscriptionPlan,Tenant,TenantSubscription}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SubscriptionService {
 public function provisionTrial(Tenant $tenant):TenantSubscription{$plan=SubscriptionPlan::where('is_active',true)->orderBy('monthly_price')->first()??SubscriptionPlan::create(['code'=>'starter','name'=>'Starter Trial','description'=>'Default trial plan; configure before commercial use.','currency_code'=>'USD','monthly_price'=>'0','annual_price'=>'0','is_active'=>true]);$now=now();return TenantSubscription::create(['tenant_id'=>$tenant->id,'plan_id'=>$plan->id,'billing_cycle'=>'monthly','state'=>'trialing','trial_ends_at'=>$now->copy()->addDays((int)config('services.billing.trial_days',14)),'current_period_starts_at'=>$now,'current_period_ends_at'=>$now->copy()->addDays(30),'provider'=>config('services.billing.provider','manual'),'seat_count'=>1]);}
 public function active(Tenant $tenant):TenantSubscription{$subscription=TenantSubscription::where('tenant_id',$tenant->id)->with('plan.features')->firstOrFail();if($subscription->state==='trialing'&&$subscription->trial_ends_at?->isPast()){$subscription->update(['state'=>'past_due','grace_ends_at'=>now()->addDays((int)config('services.billing.grace_days',7))]);$subscription->refresh();}if(in_array($subscription->state,['suspended','canceled'],true))throw ValidationException::withMessages(['subscription'=>['The tenant subscription does not permit this operation.']]);return $subscription;}
 public function limit(string $tenantId,string $feature,int $current):void{$subscription=TenantSubscription::where('tenant_id',$tenantId)->with('plan.features')->firstOrFail();$feature=$subscription->plan->features->firstWhere('feature_key',$feature);if(!$feature||$feature->value_type!=='integer')return;if($current>=(int)$feature->value)throw ValidationException::withMessages(['entitlement'=>["The plan limit for {$feature->feature_key} has been reached."]]);}
 public function changePlan(string $tenantId,string $planId,string $cycle):TenantSubscription{return DB::transaction(function()use($tenantId,$planId,$cycle){$subscription=TenantSubscription::where('tenant_id',$tenantId)->lockForUpdate()->firstOrFail();$plan=SubscriptionPlan::where('is_active',true)->findOrFail($planId);if(!in_array($cycle,['monthly','annual'],true))throw ValidationException::withMessages(['billing_cycle'=>['Unsupported billing cycle.']]);$subscription->update(['plan_id'=>$plan->id,'billing_cycle'=>$cycle,'state'=>'active','current_period_starts_at'=>now(),'current_period_ends_at'=>now()->addMonths($cycle==='annual'?12:1),'grace_ends_at'=>null,'canceled_at'=>null]);return $subscription->fresh('plan.features');});}
 public function cancel(string $tenantId):TenantSubscription{$subscription=TenantSubscription::where('tenant_id',$tenantId)->lockForUpdate()->firstOrFail();$subscription->update(['state'=>'canceled','canceled_at'=>now()]);return $subscription->fresh();}
 public function webhook(string $provider,string $raw,string $signature,array $payload):BillingWebhookEvent{$secret=config('services.billing.webhook_secrets.'.$provider);abort_unless($secret,503,'Billing provider is not configured.');$expected=hash_hmac('sha256',$raw,$secret);abort_unless(hash_equals($expected,$signature),401,'Invalid billing webhook signature.');return DB::transaction(function()use($provider,$payload){$event=BillingWebhookEvent::firstOrCreate(['provider'=>$provider,'provider_event_id'=>(string)($payload['id']??'')],['event_type'=>(string)($payload['type']??'unknown'),'payload'=>$payload,'signature_verified'=>true,'state'=>'received']);if($event->state==='processed')return $event;$event->update(['state'=>'processed','processed_at'=>now()]);$external=(string)($payload['data']['subscription_id']??'');if($external){$subscription=TenantSubscription::where('provider',$provider)->where('provider_subscription_id',$external)->lockForUpdate()->first();if($subscription){$state=(string)($payload['data']['state']??'');if(in_array($state,['active','past_due','suspended','canceled'],true))$subscription->update(['state'=>$state]);}}return $event;});}
}
